import itertools

def get_ranks(n, alpha, beta, tie_break_x):
    # Find all (x, y) such that alpha*x + beta*y <= alpha*(n-1) + beta*(n-1)
    # We only need to consider x, y up to some limit.
    # The max rank we care about is the rank of (n-1, n-1).
    max_val = alpha * (n - 1) + beta * (n - 1)
    points = []
    # We need all (x, y) such that alpha*x + beta*y <= max_val
    # x can go up to max_val // alpha
    for x in range(max_val // alpha + 1):
        # y can go up to (max_val - alpha*x) // beta
        for y in range((max_val - alpha*x) // beta + 1):
            points.append((x, y))

    # Sort points by alpha*x + beta*y, then by tie-break
    if tie_break_x:
        points.sort(key=lambda p: (alpha * p[0] + beta * p[1], p[0]))
    else:
        points.sort(key=lambda p: (alpha * p[0] + beta * p[1], p[1]))

    rank_map = {p: i for i, p in enumerate(points)}

    N = 0
    for x in range(n):
        for y in range(n):
            if rank_map[(x, y)] % 2 == 1:
                N += 1
    return N

