def get_ranks_simple(n, alpha, beta, tie_break_x):
    # For a given (x, y), we need to count how many (x', y') satisfy the condition.
    # (x', y') must satisfy alpha*x' + beta*y' <= alpha*x + beta*y.
    # Since alpha, beta > 0, x' can range from 0 to (alpha*x + beta*y)//alpha.
    # For each x', y' can range from 0 to (alpha*x + beta*y - alpha*x')//beta.

    N_odd = 0
    for x in range(n):
        for y in range(n):
            V = alpha * x + beta * y
            rank = 0
            # Count (x', y') such that alpha*x' + beta*y' < V
            # x' can go from 0 to (V-1)//alpha
            for xp in range((V - 1) // alpha + 1):
                rank += (V - 1 - alpha * xp) // beta + 1

            # Count (x', y') such that alpha*x' + beta*y' == V and tie-break
            # alpha*xp + beta*yp = V => beta*yp = V - alpha*xp
            # xp must be such that (V - alpha*xp) is divisible by beta.
            # Then yp = (V - alpha*xp) // beta.
            # We need to check if xp < x (if tie_break_x) or yp < y (if not tie_break_x).
            for xp in range(V // alpha + 1):
                if (V - alpha * xp) % beta == 0:
                    yp = (V - alpha * xp) // beta
                    if tie_break_x:
                        if xp < x:
                            rank += 1
                    else:
                        if yp < y:
                            rank += 1
            if rank % 2 == 1:
                N_odd += 1
    return N_odd

